function longestJointRun(n: number, batteries: number[]): number {
  let sum = 0;
  for (const b of batteries) sum += b;
  let lo = 0, hi = Math.floor(sum / n);
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    let usable = 0;
    for (const b of batteries) usable += Math.min(b, mid);
    if (usable >= n * mid) lo = mid;
    else hi = mid - 1;
  }
  return lo;
}

