class Solution:
    def longestJointRun(self, n: int, batteries: List[int]) -> int:
        lo, hi = 0, sum(batteries) // n
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if sum(min(b, mid) for b in batteries) >= n * mid:
                lo = mid
            else:
                hi = mid - 1
        return lo

