function longestJointRun(n: number, batteries: number[]): number {
  const b = batteries.slice().sort((x, y) => y - x);
  let sum = 0;
  for (const x of b) sum += x;
  let i = 0;
  // the largest battery outlasts the even share: it alone powers one laptop for the whole run
  while (b[i] > Math.floor(sum / n)) {
    sum -= b[i];
    n--;
    i++;
  }
  return Math.floor(sum / n);
}

